CREATE OR ALTER FUNCTION [dbo].[GenerateAssetUrl] ( @AssetID bigint ) RETURNS varchar(500) AS BEGIN declare @Url varchar(500) = ''; declare @Type varchar(50), @TypeID int, @ObjectID int = 0, @uid uniqueidentifier, @typeUid uniqueidentifier;
select @ObjectID = A.ObjectID, @Type = A.[Object], @TypeID = T.ObjectID, @uid = A.uid, @typeUid = T.uid from Asset A inner join AssetType T on T.ID = A.AssetTypeID where A.ID = @AssetID;
SET @Url = CASE @Type WHEN 'Artifact' THEN 'asset/' + CAST(@uid as nvarchar(max)) WHEN 'ReferenceItem' THEN 'assets/' + lower(cast(@typeUid as nvarchar(36))) WHEN 'Group' THEN 'group/' + CAST(@ObjectID as varchar) WHEN 'Policy' THEN 'asset/' + CAST(@uid as nvarchar(max)) WHEN 'Resource' THEN 'users/' + CAST(@uid as nvarchar(max)) WHEN 'Rule' THEN 'asset/' + CAST(@uid as nvarchar(max)) WHEN 'Taxonomy' THEN 'asset/' + CAST(@uid as nvarchar(max)) WHEN 'Task' THEN (SELECT '/asset/'+lower(cast(a.uid as nvarchar(36)))+'/diagrams/Process/' + lower(cast(@uid as nvarchar(36))) FROM AssetProcessDiagram APD CROSS APPLY (SELECT * FROM OPENJSON(APD.Diagram,'$.nodeDataArray') WITH ( uid uniqueidentifier '$.key' )) D INNER JOIN asset a on a.id = apd.AssetID WHERE D.uid = @uid) END
RETURN @Url END
